import { test, expect } from "@playwright/test";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

// M3.4: /batch/001 is generated by the site/app/batch/[nnn] route from
// site/content/batches/001.json (D48), so this test checks the rendered
// page's facts and copy against that JSON, byte-for-byte where the source
// is a fact or a label line, rather than diffing markup against a
// hand-written file (that comparison now belongs to
// scripts/check-batch-001.mjs, which diffs the deployed site against the
// built site/out/batch/001/index.html).

const contentPath = join(
  fileURLToPath(new URL(".", import.meta.url)),
  "..",
  "content",
  "batches",
  "001.json"
);

function squash(text) {
  return text.replace(/\s+/g, " ").trim();
}

test("/batch/001 carries the printed-jar facts and ingredient line, and stays local", async ({
  page,
  baseURL,
}) => {
  const batch = JSON.parse(await readFile(contentPath, "utf8"));

  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));

  const foreignRequests = [];
  const localOrigin = new URL(baseURL).origin;
  page.on("request", (req) => {
    const origin = new URL(req.url()).origin;
    if (origin !== localOrigin) foreignRequests.push(req.url());
  });

  const response = await page.goto("/batch/001");
  expect(response.status()).toBe(200);

  await expect(page).toHaveTitle("Batch 001. Prawns and dates. Lailark");
  await expect(page.locator('meta[name="description"]')).toHaveAttribute(
    "content",
    batch.facts.join(" ")
  );

  await expect(page.locator(".batch-hero__no")).toHaveText("Batch 001");
  await expect(page.locator(".batch-hero__name")).toHaveText("Prawns and dates");

  const factsText = squash(await page.locator(".batch-facts").innerText());
  for (const fact of batch.facts) expect(factsText).toContain(fact);

  const bodyText = squash(await page.locator("body").innerText());

  // The ingredient line, character for character, with no percentages
  // (D28): plain names joined by ", " and ending in a period.
  const ingredientLine = `${batch.ingredients.map((i) => i.name).join(", ")}.`;
  expect(ingredientLine).not.toMatch(/%/);
  expect(bodyText).toContain(ingredientLine);

  expect(bodyText).toContain(batch.allergens);
  expect(bodyText).toContain(batch.claims);
  expect(bodyText).toContain(batch.storage);
  expect(bodyText).toContain(batch.bestBefore);
  expect(bodyText).toContain(
    "Lailark Kitchen. Neduvanchalil Veedu, Kunnamangalam, Kozhikode, Kerala, India, PIN 673571."
  );
  expect(bodyText).toContain("FSSAI 21323244000035");

  // No Legal Metrology block, no price and no buy button on the record page
  // (D47): those belong to /pickles/<slug>, not here.
  expect(bodyText).not.toContain("MRP");
  expect(bodyText).not.toMatch(/₹/);
  await expect(page.locator(".product-buy")).toHaveCount(0);

  // D48: the page ends with one action, to the home page, naming no
  // product, no price and no stock.
  const cta = page.locator(".batch-cta");
  await expect(cta).toHaveText(/See what we make/);
  await expect(cta).toHaveAttribute("href", "/");
  await expect(page.locator('a[href*="wa.me"]')).toHaveCount(0);

  // The jar-in-hand photo (D50): alt text only, no caption text near it.
  const photo = page.locator(".batch-photo");
  await expect(photo).toHaveAttribute("src", "/assets/jar-001.jpg");
  await expect(photo).toHaveAttribute("alt", /.+/);

  await page.waitForTimeout(300);
  expect(consoleErrors).toEqual([]);
  expect(foreignRequests).toEqual([]);
});

// /batch/1 and /batch/01 redirecting to /batch/001 is a Firebase Hosting
// config rule (firebase.json's "redirects", untouched by this task), not
// something the site's own Next.js output serves: scripts/serve-out.mjs
// (this Playwright suite's webServer) is a plain static file server with
// no knowledge of firebase.json, and the local emulator suite does not run
// here. That redirect is covered by scripts/check-batch-001.mjs and its
// own test, scripts/test/check-batch-001.test.mjs, against a server that
// reproduces firebase.json's redirect rules.
